// Loads the trimmed dictionary generated by scripts/build-dictionary.mjs.
// Everything downstream just does `ids[char]` / `info[char]`, so it doesn't
// care where this data came from.
export async function loadDictionary() {
  const res = await fetch(`${import.meta.env.BASE_URL}dictionary.json`);
  if (!res.ok) throw new Error(`Failed to load dictionary (${res.status})`);
  return res.json(); // { ids, info }
}
